#pragma once
#include <string>
namespace axon::portfolio::web {
inline std::string page() {
    return R"HTML(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Axon Capability Atlas</title></head><body><header><b>AXON / CAPABILITY ATLAS</b><output id="state" aria-live="polite">Connect a portfolio</output></header><main><aside><label>Keycloak access token<input id="t" type="password" autocomplete="off"></label><button id="go">Load portfolio</button><label>Search<input id="search" type="search" autocomplete="off" placeholder="Capability, path or contract"></label><label>Repository<select id="repo"><option value="">All repositories</option></select></label><label><input id="links" type="checkbox" checked> convergence links</label><p id="counts">No topology loaded</p></aside><section><h1>Portfolio topology</h1><p id="topology-note">A bounded, read-only map of implementations and convergence candidates.</p><div id="map"><svg id="graph" viewBox="0 0 1000 620" role="img" aria-label="Interactive capability topology"><g id="world"></g></svg><p id="empty">Load portfolio to draw the atlas.</p></div><div id="edges" aria-label="Capability convergence candidates"></div></section><aside><h2 id="selection-title">Evidence inspector</h2><div id="detail" tabindex="-1">Select a capability or relationship.</div><h3>Declaration drift</h3><label>Registered graph root<input id="graph-root" autocomplete="off"></label><label>Fragment<input id="fragment" autocomplete="off"></label><button id="drift">Check drift</button></aside></main><script>
const $=id=>document.getElementById(id),S={n:[],e:[],z:1,x:0,y:0};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,d){let r=await fetch(p,{headers:{Authorization:'Bearer '+$('t').value}}),b=await r.json();if(!r.ok&&!(d&&r.status===503))throw Error(b.error||r.status);return b}function draw(){let q=$('search').value.toLowerCase(),r=$('repo').value,n=S.n.filter(x=>(!r||x.repository_id===r)&&(!q||[x.name,x.path,...(x.contracts||[])].join(' ').toLowerCase().includes(q))),ids=new Set(n.map(x=>x.id)),e=$('links').checked?S.e.filter(x=>ids.has(x.source)&&ids.has(x.target)):[],w=$('world');w.replaceChildren();$('empty').hidden=!!n.length;$('counts').textContent=`${n.length} capabilities · ${e.length} links`;$('topology-note').textContent=n.length?'Drag to pan; wheel to zoom; select nodes for provenance.':'No capabilities match the filter.';let rs=[...new Set(n.map(x=>x.repository_id))],p=new Map();rs.forEach((v,j)=>n.filter(x=>x.repository_id===v).forEach((x,i)=>p.set(x.id,{x:140+j*720/Math.max(1,rs.length-1),y:110+i*420/Math.max(1,n.filter(a=>a.repository_id===v).length-1)})));e.forEach(a=>{let x=p.get(a.source),y=p.get(a.target);if(!x||!y)return;let l=document.createElementNS('http://www.w3.org/2000/svg','line');l.setAttribute('x1',x.x);l.setAttribute('y1',x.y);l.setAttribute('x2',y.x);l.setAttribute('y2',y.y);l.setAttribute('class','edge');l.onclick=()=>compare(a);w.append(l)});n.forEach(a=>{let x=p.get(a.id),g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','node');g.setAttribute('transform',`translate(${x.x} ${x.y})`);g.setAttribute('tabindex','0');g.innerHTML=`<circle r="20"></circle><text y="42">${esc(a.name)}</text><text class="path" y="58">${esc(a.path||a.repository_id)}</text>`;g.onclick=()=>node(a);w.append(g)});$('edges').innerHTML=e.map(a=>`<button data-id="${esc(a.id)}">${esc(a.classification.replaceAll('_',' '))} · ${Math.round(a.score*100)}%</button>`).join('');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>compare(S.e.find(x=>x.id===b.dataset.id)));w.setAttribute('transform',`translate(${S.x} ${S.y}) scale(${S.z})`)}async function node(n){try{let c=await api('/api/v1/capabilities/consumers/'+encodeURIComponent(n.id));$('selection-title').textContent=n.name;$('detail').innerHTML=`<b>Repository</b><p>${esc(n.repository_id)}</p><b>Path</b><p>${esc(n.path)}</p><b>Contracts</b><p>${esc((n.contracts||[]).join(', ')||'—')}</p><b>Consumers</b><p>${esc((c.consumer_capabilities||[]).join(', ')||'—')}</p><b>Package hints</b><p>${esc((c.unresolved_import_specifiers||[]).join(', ')||'—')}</p>`;$('detail').focus()}catch(e){$('state').textContent=e.message}}async function compare(e){let r=await api('/api/v1/capabilities/compare/'+encodeURIComponent(e.id));$('selection-title').textContent=r.classification.replaceAll('_',' ');$('detail').innerHTML=`<h1>${Math.round(r.score*100)}%</h1><b>Differences</b><p>${esc((r.differences||[]).join(' · ')||'None')}</p><b>Invalidators</b><p>${esc((r.invalidators||[]).join(' · ')||'None')}</p>`;$('detail').focus()}async function load(){try{let[a,b]=await Promise.all([api('/api/v1/portfolio/status',true),api('/api/v1/portfolio/topology?limit=100')]);S.n=b.nodes||[];S.e=b.edges||[];$('repo').innerHTML='<option value="">All repositories</option>'+[...new Set(S.n.map(x=>x.repository_id))].map(x=>`<option>${esc(x)}</option>`).join('');$('state').textContent=a.degraded?'Degraded projection':'Fresh projection';draw()}catch(e){$('state').textContent='Unavailable: '+e.message}}$('go').onclick=load;['search','repo','links'].forEach(x=>$(x).oninput=draw);$('drift').onclick=async()=>{try{let r=await api('/api/v1/capabilities/drift?graph_root='+encodeURIComponent($('graph-root').value)+'&fragment='+encodeURIComponent($('fragment').value));$('selection-title').textContent='Declaration drift';$('detail').textContent=`${r.matches} matches · ${r.drift} drift`; }catch(e){$('state').textContent=e.message}};let down,last;$('graph').onpointerdown=e=>{down=true;last=e};$('graph').onpointermove=e=>{if(!down)return;S.x+=e.clientX-last.clientX;S.y+=e.clientY-last.clientY;last=e;draw()};$('graph').onpointerup=()=>down=false;$('graph').onwheel=e=>{e.preventDefault();S.z=Math.max(.6,Math.min(2.5,S.z*(e.deltaY<0?1.1:.9)));draw()};</script><style>:root{--ink:#14252b;--paper:#edf1ec;--sea:#126b68;--coral:#d2583f;--line:#c5d0c9}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px system-ui}header{height:58px;padding:18px 24px;background:white;border-bottom:1px solid var(--line);letter-spacing:.08em}output{float:right;color:var(--sea);letter-spacing:0}main{display:grid;grid-template-columns:240px 1fr 300px;min-height:calc(100vh - 58px)}aside{padding:20px;background:#f8faf6;border-right:1px solid var(--line)}aside:last-child{border-left:1px solid var(--line);border-right:0}section{padding:28px;min-width:0}h1{font:600 28px Georgia;margin:0 0 8px}h2{font:600 20px Georgia}h3,b{font-size:12px;text-transform:uppercase;letter-spacing:.08em}label{display:block;font-size:12px;font-weight:bold;margin:15px 0}input,select{display:block;width:100%;margin-top:5px;padding:8px;border:1px solid var(--line);background:white}button{padding:8px 10px;color:white;background:var(--sea);border:1px solid var(--sea);cursor:pointer}#map{height:min(65vh,650px);min-height:420px;position:relative;overflow:hidden;border:1px solid var(--line);background:radial-gradient(#d4ddd7 1px,transparent 1px)/18px 18px}svg{width:100%;height:100%;touch-action:none}.edge{stroke:#8da69f;stroke-width:2}.node{cursor:pointer}.node circle{fill:white;stroke:var(--sea);stroke-width:3}.node:hover circle{fill:#e6ad44}.node text{text-anchor:middle;font-size:13px;font-weight:bold}.node .path{font-size:10px;font-weight:normal;fill:#64736e}#empty{position:absolute;top:45%;width:100%;text-align:center;color:#64736e}#edges{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}#edges button{background:white;color:var(--ink);border-color:var(--line)}#detail{overflow-wrap:anywhere;line-height:1.5}#detail h1{color:var(--coral)}@media(max-width:950px){main{grid-template-columns:1fr}aside{border-bottom:1px solid var(--line)}aside:last-child{border-left:0}.canvas{order:-1}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}</style></body></html>)HTML";
}
} // namespace axon::portfolio::web
